    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - b + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span> و <span dir=\"ltr\" class=\"expr\">b = 2</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>) - 2 + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"}],
