    correction: [{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">-1 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> - x = 1</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-1 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> = -<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span> - x = 1</span>"},{"quoi":"المجهول هو الفرق","math":"<span dir=\"ltr\" class=\"expr\">x = (-<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">4</span></span>) - 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">19</span><span class=\"den\">4</span></span></span>"}],
