    correction: [{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|x| = 1 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">1 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> = -<span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">10</span></span></span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">21</span><span class=\"den\">10</span></span> &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد كسري نسبي x يحقّق المعادلة"}],
